def _sigmoid_row_mean_kernel(x_ref, y_ref, mean_ref):
    x = x_ref[...].astype(jnp.float32)
    y = jax.nn.sigmoid(x)
    y_ref[...] = y.astype(y_ref.dtype)
    row_mean = jnp.sum(y, axis=-1) * (1.0 / y.shape[-1])
    mean_ref[...] = row_mean.reshape(mean_ref.shape).astype(mean_ref.dtype)


@jax.jit
def workload(x):
    m, n = x.shape
    if m % 16 == 0:
        rows = 16
    elif m % 8 == 0:
        rows = 8
    else:
        rows = m

    y, row_mean = pl.pallas_call(
        _sigmoid_row_mean_kernel,
        out_shape=(
            jax.ShapeDtypeStruct(x.shape, x.dtype),
            jax.ShapeDtypeStruct((m, 1), x.dtype),
        ),
        grid=(m // rows,),
        in_specs=[
            pl.BlockSpec((rows, n), lambda i: (i, 0)),
        ],
        out_specs=[
            pl.BlockSpec((rows, n), lambda i: (i, 0)),
            pl.BlockSpec((rows, 1), lambda i: (i, 0)),
        ],
        compiler_params=pltpu.CompilerParams(
            dimension_semantics=("parallel",)
        ),
    )(x)
